<script setup>
import{onMounted,ref}from'vue';import{api}from'../services/api'
const metadata=ref({}),options=ref({}),status=ref('');const fields=[['title','Título'],['publisher','Editorial'],['identifier','Identificador / ISBN-NIMAS'],['source_isbns','ISBN de origen'],['language','Idioma'],['copyright_year','Año de copyright'],['publication_year','Año de publicación'],['edition','Edición'],['content_type','Tipo de contenido'],['state_edition','Edición estatal'],['subjects','Materias'],['grade_levels','Grados']];const roles=[['author','Autores'],['illustrator','Ilustradores'],['editor','Editores']]
function people(role){return(metadata.value.creators||[]).filter(x=>String(x.role||'author').toLowerCase()===role).map(x=>x.name||x).join('; ')}function setPeople(role,value){const others=(metadata.value.creators||[]).filter(x=>String(x.role||'author').toLowerCase()!==role);const current=value.split(';').map(name=>name.trim()).filter(Boolean).map(name=>({name,role}));metadata.value.creators=[...others,...current]}
onMounted(async()=>{const d=await api.projectDetail();metadata.value=d.metadata||{};options.value=await api.nimacTemplate()});async function save(){await api.saveSetup({metadata:metadata.value});status.value='Metadata guardada.'}
</script>
<template><section class="hero"><span class="eyebrow">PASO 2 · METADATA</span><h2>Metadata NIMAC</h2><p>Completa estos datos después de aprobar las lecciones. Confirma el idioma principal antes de generar propuestas: controla la lectura semántica y los atributos <code>xml:lang</code>. Los permisos predeterminados del starter OPF no se solicitan.</p></section><form class="metadata-card" @submit.prevent="save"><label v-for="[key,label] in fields" :key="key">{{label}}<select v-if="options[key]" v-model="metadata[key]" :multiple="['subjects','grade_levels'].includes(key)"><option v-for="value in options[key]" :key="value">{{value}}</option></select><input v-else v-model="metadata[key]"/></label><label v-for="[role,label] in roles" :key="role">{{label}}<input :value="people(role)" aria-describedby="creator-hint" @input="setPeople(role,$event.target.value)"/><small id="creator-hint">Separa varias personas con punto y coma (;).</small></label><button type="submit">Guardar metadata</button><span class="hint">{{status}}</span></form></template>
